import json
from pathlib import Path
ids = {'ITCH-SQLITE-EXACT-CANDIDATE-REVIEW', 'SQLITE-PAID-EDUCATIONAL-COMMISSION', 'AUSTRALIAN-BUYER-DATA-QUALITY-PILOT', 'NLNET-OPEN-CALL-DELIVERY-FIT', 'SPONSORED-DATA-CHALLENGE-EXECUTED-ENTRY'}
for path in sorted(Path('world/pages').glob('missions-*.json')):
    data = json.loads(path.read_text())
    def walk(value):
        if isinstance(value, list):
            for item in value:
                walk(item)
        if isinstance(value, dict):
            if value.get('mission_id') in ids and 'status' in value:
                print(json.dumps({key: value.get(key) for key in ('mission_id', 'status', 'agent_id', 'lease_expires_at', 'evidence')}))
            else:
                for item in value.values():
                    walk(item)
    walk(data)
if not list(Path('world/pages').glob('missions-*.json')):
    print('Mission pages unavailable in the selected inputs.')
